#include "api/qkv_projection_training_api.h"
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <vector>
int main(){constexpr std::uint32_t H=5,T=7,R=4;constexpr float lr=.023f,eps=1e-3f;std::vector<float>wq(H*H),wk(H*H),wv(H*H),x(T*H),dq(T*H),dk(T*H),dv(T*H);for(size_t i=0;i<wq.size();++i){wq[i]=std::sin(i*.13f);wk[i]=std::cos(i*.11f);wv[i]=std::sin(i*.19f);}for(size_t i=0;i<x.size();++i){x[i]=std::cos(i*.17f);dq[i]=std::sin(i*.07f);dk[i]=std::cos(i*.09f);dv[i]=std::sin(i*.05f);}auto grad=[&](std::vector<float> const& d){std::vector<float> g(H*H);for(std::uint32_t h=0;h<H;++h)for(std::uint32_t o=0;o<H;++o)for(std::uint32_t t=0;t<R;++t)g[h*H+o]+=x[t*H+h]*d[t*H+o];return g;};auto gq=grad(dq),gk=grad(dk),gv=grad(dv);auto check_fd=[&](std::vector<float> const&w,std::vector<float> const&d,std::vector<float> const&g){for(std::uint32_t h=0;h<H;++h)for(std::uint32_t o=0;o<H;++o){auto p=w,m=w;p[h*H+o]+=eps;m[h*H+o]-=eps;auto objective=[&](std::vector<float> const&z){float s=0;for(std::uint32_t t=0;t<R;++t)s+=x[t*H+h]*z[h*H+o]*d[t*H+o];return s;};if(std::abs((objective(p)-objective(m))/(2*eps)-g[h*H+o])>2e-4f)return false;}return true;};if(!check_fd(wq,dq,gq)||!check_fd(wk,dk,gk)||!check_fd(wv,dv,gv))return 1;auto*xh=spaceslug_qkv_projection_training_create(wq.data(),wk.data(),wv.data(),H,T);if(!xh||spaceslug_qkv_projection_training_step(xh,x.data(),dq.data(),dk.data(),dv.data(),R,lr)!=0)return 1;std::vector<float>rq(H*H),rk(H*H),rv(H*H),rgq(H*H),rgk(H*H),rgv(H*H);if(spaceslug_qkv_projection_training_readback(xh,rq.data(),rk.data(),rv.data(),rgq.data(),rgk.data(),rgv.data())!=0)return 1;float e=0;for(size_t i=0;i<gq.size();++i){e=std::max(e,std::abs(rgq[i]-gq[i]));e=std::max(e,std::abs(rgk[i]-gk[i]));e=std::max(e,std::abs(rgv[i]-gv[i]));e=std::max(e,std::abs(rq[i]-(wq[i]-lr*gq[i])));e=std::max(e,std::abs(rk[i]-(wk[i]-lr*gk[i])));e=std::max(e,std::abs(rv[i]-(wv[i]-lr*gv[i])));}spaceslug_qkv_projection_training_destroy(xh);if(e>3e-5f){std::cerr<<"QKV mismatch "<<e<<'\n';return 1;}std::cout<<"QKV projection training: PASS max_error="<<e<<'\n';return 0;}
